		{"negative", "-3"},
		{"min int64", "-9223372036854775808"},
		{"not an integer", "two"},
		{"not a whole number", "1.5"},
		{"empty", ""},
		{"above max int64", "9223372036854775808"},
		{"far above max int64", "99999999999999999999999999"},
	}
