package edgefleet

import (
	"bytes"
	"errors"
	"io"
	"strings"
	"testing"
)

var scratchReadErr = errors.New("scratch upstream failure")

func TestScratchReadErrorMidRecord(t *testing.T) {
	event := `{"type":"event","key":"k","time":100,"value":2}` + "\n"
	wm := `{"type":"watermark","time":1000}`

	// Case 1: watermark JSON delivered without newline, error on next read.
	var out, late bytes.Buffer
	r := &failingAfterReader{data: []byte(event + wm), failAt: len(event) + len(wm), err: scratchReadErr}
	err := RunAggregate(r, 1000, &out, &late)
	t.Logf("case1 err=%v out=%q late=%q", err, out.String(), late.String())
	if !errors.Is(err, scratchReadErr) {
		t.Errorf("case1: want read error via errors.Is, got %v", err)
	}
	if out.String() != "" {
		t.Errorf("case1: must not emit [0,1000), got %q", out.String())
	}

	// Case 2: watermark newline received in the SAME read that carries the error.
	var out2, late2 bytes.Buffer
	input2 := event + wm + "\n"
	r2 := &failingAfterReader{data: []byte(input2), failAt: len(input2), err: scratchReadErr, errOnBoundary: true, chunk: 1 << 20}
	err2 := RunAggregate(r2, 1000, &out2, &late2)
	t.Logf("case2 err=%v out=%q", err2, out2.String())
	if !errors.Is(err2, scratchReadErr) {
		t.Errorf("case2: want read error, got %v", err2)
	}
	want2 := `{"key":"k","start":0,"end":1000,"count":1,"sum":2}` + "\n"
	if out2.String() != want2 {
		t.Errorf("case2: window must be emitted before failing:\n got %q\nwant %q", out2.String(), want2)
	}

	// Case 3: clean EOF, final valid JSON without newline -> processed, no error.
	var out3, late3 bytes.Buffer
	err3 := RunAggregate(strings.NewReader(event+wm), 1000, &out3, &late3)
	t.Logf("case3 err=%v out=%q", err3, out3.String())
	if err3 != nil {
		t.Errorf("case3: clean EOF must succeed, got %v", err3)
	}
	if out3.String() != want2 {
		t.Errorf("case3: final unterminated watermark must close window:\n got %q\nwant %q", out3.String(), want2)
	}

	// Case 4: clean EOF, final broken JSON -> InputError physical line 2.
	var out4, late4 bytes.Buffer
	err4 := RunAggregate(strings.NewReader(event+`{"type":"watermark","time":1000`), 1000, &out4, &late4)
	t.Logf("case4 err=%v out=%q", err4, out4.String())
	var ie *InputError
	if !errors.As(err4, &ie) || ie.Line != 2 {
		t.Errorf("case4: want *InputError line 2, got %v", err4)
	}
	if out4.String() != "" {
		t.Errorf("case4: no window output, got %q", out4.String())
	}

	// Case 5: read error after a blank line (without newline) - blank tail not counted.
	var out5, late5 bytes.Buffer
	r5 := &failingAfterReader{data: []byte(event + "\n"), failAt: len(event) + 1, err: scratchReadErr}
	err5 := RunAggregate(r5, 1000, &out5, &late5)
	t.Logf("case5 err=%v out=%q", err5, out5.String())
	if !errors.Is(err5, scratchReadErr) {
		t.Errorf("case5: %v", err5)
	}

	// Case 6: read error where the error read ALSO delivers the event line+newline.
	var out6, late6 bytes.Buffer
	r6 := &failingAfterReader{data: []byte(event + wm), failAt: len(event), err: scratchReadErr, errOnBoundary: true, chunk: 1 << 20}
	err6 := RunAggregate(r6, 1000, &out6, &late6)
	t.Logf("case6 err=%v out=%q", err6, out6.String())
	if !errors.Is(err6, scratchReadErr) {
		t.Errorf("case6: %v", err6)
	}
	if out6.String() != "" {
		t.Errorf("case6: event complete but no watermark -> no output, got %q", out6.String())
	}
}

// silence unused
var _ = io.EOF

