cat > edgefleet/scratch_long_test.go <<'EOF'
package edgefleet

import (
	"bytes"
	"errors"
	"strings"
	"testing"
)

func TestScratchLongLine(t *testing.T) {
	// A 100KiB key forces buffer growth mid-record, delivered one byte at a time.
	key := strings.Repeat("k", 100*1024)
	rec := `{"type":"event","key":"` + key + `","time":100,"value":2}` + "\n" +
		`{"type":"watermark","time":1000}` // unterminated final, clean EOF
	cuts := make([]int, 0, len(rec)-1)
	for at := 1; at < len(rec); at++ {
		cuts = append(cuts, at)
	}
	var out, late bytes.Buffer
	if err := RunAggregate(newChunkReader(rec, cuts...), 1000, &out, &late); err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(out.String(), `"start":0,"end":1000,"count":1,"sum":2`) {
		t.Fatalf("output mismatch: %.120q", out.String())
	}

	// >1 GiB single line -> errAggregateLineTooLong (cap near growth limit).
	big := strings.Repeat("x", maxAggregateLineBytes+1)
	var out2, late2 bytes.Buffer
	err := RunAggregate(strings.NewReader(big), 1000, &out2, &late2)
	if !errors.Is(err, errAggregateLineTooLong) {
		t.Fatalf("got %v", err)
	}
}
EOF
go test ./edgefleet/ -run TestScratchLongLine -v 2>&1 | tail -5; rm edgefleet/scratch_long_test.go
